const handleStartExtraction = routine(
  ofType(startExtraction),
  extractPayload(),
  exhaustMap(({ extractionDraftId, files }) =>
    from(
      extractionDocumentApi.startExtraction({ extractionDraftId, files })
    ).pipe(
      handleError(error => {
        api.logErrorIfNeeded(error);
        dispatchAction(startExtractionFailed(error));
      }),
      tap(response => dispatchAction(extractionStarted(response)))
    )
  )
);

